    N = int(data[0])
    strings = []
    costs = []
    for line in data[1:]:
        s, c = line.split()
        c = int(c)
        strings.append(s)
        costs.append(c)
    min_cost = float('inf')

    # Check for single string palindromes
    for i in range(N):
        if is_palindrome(strings[i]):
            if costs[i] < min_cost:
                min_cost = costs[i]

    # Check all pairs of strings
    for i in range(N):
        for j in range(N):
            s1 = strings[i] + strings[j]
            if is_palindrome(s1):
                total = costs[i] + costs[j]
                if total < min_cost:
                    min_cost = total
            s2 = strings[j] + strings[i]
            if is_palindrome(s2):
                total = costs[i] + costs[j]
                if total < min_cost:
                    min_cost = total

    if min_cost == float('inf'):
        print(-1)
