        elif machine == 'p':
            points[i][0] = 0  # Rock vs Paper: lose
            points[i][1] = 0  # Paper vs Paper: draw
            points[i][2] = S  # Scissors vs Paper: win
        else:  # 's'
            points[i][0] = R  # Rock vs Scissors: win
            points[i][1] = 0  # Paper vs Scissors: lose
            points[i][2] = 0  # Scissors vs Scissors: draw

    # Initialize dp array
    dp = [[0]*3 for _ in range(N)]

    # Process each round
    for i in range(N):
        if i == 0:
            for h in range(3):
                dp[i][h] = points[i][h]
        else:
            if i < K:
                max_prev = max(dp[i-1][0], dp[i-1][1], dp[i-1][2])
                for h in range(3):
                    dp[i][h] = max_prev + points[i][h]
            else:
                prev_group = i - K
                # Compute max1 and max2 for prev_group
                values = [(dp[prev_group][0], 0), (dp[prev_group][1], 1), (dp[prev_group][2], 2)]
