from functools import lru_cache

MOD = 10**9 + 7

def main():
    n, k = map(int, sys.stdin.readline().split())
    if k % 2 != 0:
        print(0)
        return

    @lru_cache(maxsize=None)
    def dp(mask, sum_so_far):
        if sum_so_far > k:
            return 0
        if mask == (1 << n) - 1:
            return 1 if sum_so_far == k else 0
        res = 0
        for i in range(n):
            if not (mask & (1 << i)):
                for j in range(n):
                    if not (mask & (1 << j)):
                        new_mask = mask | (1 << i) | (1 << j)
                        contribution = abs((i + 1) - (j + 1))
                        res += dp(new_mask, sum_so_far + contribution)
                        res %= MOD
        return res

    print(dp(0, 0) % MOD)

