            for x in range(1, n+1):
                if not (mask & (1 << (x-1))):
                    contribution = abs(i + 1 - x)
                    new_mask = mask | (1 << (x-1))
                    new_s = s + contribution
                    if new_s > max_sum:
                        continue
                    dp[new_mask][new_s] = (dp[new_mask][new_s] + count) % MOD

    print(dp[(1 << n) - 1][k] % MOD)

