def factorize(x):
    factors = {}
    i = 2
    while i * i <= x:
        while x % i == 0:
            factors[i] = factors.get(i, 0) + 1
            x = x // i
        i += 1
    if x > 1:
        factors[x] = 1
    return factors

def generate_divisors(factors):
    divisors = [1]
    for p, exp in factors.items():
        current_length = len(divisors)
        p_powers = [p**e for e in range(1, exp+1)]
        for d in divisors[:current_length]:
            for power in p_powers:
                divisors.append(d * power)
    return divisors

