    for a in A:
        for bit in range(max_bit + 1):
            if a & (1 << bit):
                count_ones[bit] += 1

    @lru_cache(maxsize=None)
    def dfs(bit, tight):
        if bit < 0:
            return 0
        max_bit_val = (K >> bit) & 1 if tight else 1
