                continue
            if choice == 0:
                contrib = count_ones[bit] * (1 << bit)
            else:
                contrib = (N - count_ones[bit]) * (1 << bit)
            new_tight = tight and (choice == max_bit_val)
            res = max(res, contrib + dfs(bit - 1, new_tight))
        return res

    result = dfs(max_bit, True)
    print(result)

