from collections import defaultdict

MOD = 998244353

class DSU:
    def __init__(self, size):
        self.parent = list(range(size))
        self.rank = [0] * size

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        x_root = self.find(x)
        y_root = self.find(y)
        if x_root == y_root:
            return
        if self.rank[x_root] < self.rank[y_root]:
            self.parent[x_root] = y_root
        else:
            self.parent[y_root] = x_root
            if self.rank[x_root] == self.rank[y_root]:
                self.rank[x_root] += 1

def main():
    input = sys.stdin.read().split()
    ptr = 0
    N = int(input[ptr])
    ptr += 1
    K = int(input[ptr])
    ptr += 1
    a = []
    for _ in range(N):
        row = list(map(int, input[ptr:ptr+N]))
        a.append(row)
        ptr += N

    # Process rows DSU
    rows_dsu = DSU(N)
    for i in range(N):
        for j in range(i + 1, N):
            can_swap = True
            for c in range(N):
                if a[i][c] + a[j][c] > K:
                    can_swap = False
                    break
            if can_swap:
                rows_dsu.union(i, j)

    # Process columns DSU
    cols_dsu = DSU(N)
    for x in range(N):
        for y in range(x + 1, N):
            can_swap = True
            for i in range(N):
                if a[i][x] + a[i][y] > K:
                    can_swap = False
                    break
            if can_swap:
                cols_dsu.union(x, y)

    # Compute row component sizes
    row_components = defaultdict(int)
    for i in range(N):
        root = rows_dsu.find(i)
        row_components[root] += 1

    # Compute column component sizes
    col_components = defaultdict(int)
    for x in range(N):
        root = cols_dsu.find(x)
        col_components[root] += 1

    # Precompute factorials up to N
    max_fact = N
    fact = [1] * (max_fact + 1)
    for i in range(1, max_fact + 1):
        fact[i] = fact[i - 1] * i % MOD

    # Calculate row product
    row_product = 1
    for s in row_components.values():
        row_product = row_product * fact[s] % MOD

    # Calculate column product
    col_product = 1
    for s in col_components.values():
        col_product = col_product * fact[s] % MOD

    print((row_product * col_product) % MOD)

