from collections import defaultdict, deque

def main():
    input = sys.stdin.read().split()
    idx = 0
    N = int(input[idx])
    idx += 1
    A = []
    for _ in range(N):
        row = list(map(int, input[idx:idx + N-1]))
        A.append(row)
        idx += N-1

    # Generate all possible matches
    all_matches = set()
    for i in range(1, N+1):
        for j in range(i+1, N+1):
            all_matches.add((i, j))

    # Build graph and in_degree
    graph = defaultdict(set)
    in_degree = {node: 0 for node in all_matches}

    for i in range(N):
        player = i + 1
        for k in range(len(A[i]) - 1):
            prev_opponent = A[i][k]
            curr_opponent = A[i][k+1]
            u = (min(player, prev_opponent), max(player, prev_opponent))
            v = (min(player, curr_opponent), max(player, curr_opponent))
            if v not in graph[u]:
                graph[u].add(v)
                in_degree[v] += 1

    # Topological sort
    queue = deque()
    for node in all_matches:
        if in_degree[node] == 0:
            queue.append(node)

    topological_order = []
    while queue:
        u = queue.popleft()
        topological_order.append(u)
        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    if len(topological_order) != len(all_matches):
        print(-1)
        return

    # Longest path
    distance = {node: 0 for node in all_matches}
    for u in topological_order:
        for v in graph[u]:
            if distance[v] < distance[u] + 1:
                distance[v] = distance[u] + 1

    max_distance = max(distance.values())
