from functools import lru_cache

MOD = 10**9 + 7

def count_set_bits(x, t):
    if x < 0:
        return 0
    if t == 0:
        return 1 if x >= 0 else 0
    bits = []
    while x > 0:
        bits.append(x & 1)
        x >>= 1
    bits = bits[::-1]
    @lru_cache(maxsize=None)
    def dp(pos, tight, count_set):
        if pos == len(bits):
            return 1 if count_set == t else 0
        res = 0
        max_bit = bits[pos] if tight else 1
        for bit in [0, 1]:
            if bit > max_bit:
                continue
            new_tight = tight and (bit == max_bit)
            new_count_set = count_set + bit
            if new_count_set > t:
                continue
            res += dp(pos + 1, new_tight, new_count_set)
        return res
    return dp(0, True, 0)

def main():
    L, R = map(int, sys.stdin.readline().split())
    total = R - L + 1
    for k in range(0, 61):
        lower = 1 << k
        upper = (1 << (k + 1)) - 1
        A = max(L, lower)
        B = min(R, upper)
        if A > B:
            continue
        s_low = A - lower
        s_high = B - lower
        for t in range(0, k + 1):
            cnt_high = count_set_bits(s_high, t)
            cnt_low = count_set_bits(s_low - 1, t)
            count_t = cnt_high - cnt_low
            exponent = k - t
            term = (pow(2, exponent, MOD) - 1) % MOD
            contribution = (count_t * term) % MOD
            total = (total + contribution) % MOD
    print(total % MOD)

