def count_subsets(M, K):
    if M == 0:
        return 1 if K >= 0 else 0
    if K < 0:
        return 0
    highest_bit = M.bit_length() - 1
    if (1 << highest_bit) > K + 1:
        return count_subsets(M & ((1 << highest_bit) - 1), K)
    else:
        return count_subsets(M & ((1 << highest_bit) - 1), K) + count_subsets(M & ((1 << highest_bit) - 1), K - (1 << highest_bit))

