def count_valid_r(x, k):
    bits_x = []
    temp = x
    while temp > 0:
        bits_x.append(temp & 1)
        temp >>= 1
    bits_x = bits_x[::-1]
    bits_k = []
    temp = k
    while temp > 0:
        bits_k.append(temp & 1)
        temp >>= 1
    bits_k = bits_k[::-1]
    max_len = max(len(bits_x), len(bits_k))
    bits_x = [0] * (max_len - len(bits_x)) + bits_x
    bits_k = [0] * (max_len - len(bits_k)) + bits_k

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(pos, tight, leading_zero):
        if pos == len(bits_x):
            return 1 if leading_zero else 0
        res = 0
        max_bit = bits_k[pos] if tight else 1
        for bit in [0, 1]:
            if bit > max_bit:
