            if bit == 1 and bits_x[pos] == 1:
                continue
            new_tight = tight and (bit == max_bit)
            new_leading_zero = leading_zero and (bit == 0)
            res += dp(pos + 1, new_tight, new_leading_zero)
        return res

    return dp(0, True, True)

