def main():
    input = sys.stdin.read().split()
    idx = 0
    N = int(input[idx]); idx +=1
    Ma = int(input[idx]); idx +=1
    Mb = int(input[idx]); idx +=1
    packages = []
    for _ in range(N):
        a = int(input[idx]); idx +=1
        b = int(input[idx]); idx +=1
        c = int(input[idx]); idx +=1
        packages.append((a, b, c))

    INF = float('inf')
    max_sum = 400
    dp = [[INF] * (max_sum + 1) for _ in range(max_sum + 1)]
    dp[0][0] = 0

    for a, b, c in packages:
        temp_dp = [row[:] for row in dp]
        for sa in range(max_sum + 1):
            for sb in range(max_sum + 1):
                if temp_dp[sa][sb] != INF:
                    new_sa = sa + a
                    new_sb = sb + b
                    if new_sa <= max_sum and new_sb <= max_sum:
                        if dp[new_sa][new_sb] > temp_dp[sa][sb] + c:
                            dp[new_sa][new_sb] = temp_dp[sa][sb] + c

    min_cost = INF
    for sa in range(max_sum + 1):
        for sb in range(max_sum + 1):
            if sa * Mb == sb * Ma and (sa != 0 or sb != 0):
                if dp[sa][sb] < min_cost:
                    min_cost = dp[sa][sb]

    print(-1 if min_cost == INF else min_cost)

