            for group in groups:
                s = 0
                for i in group:
                    s += grid[i][j]
                row_group_sums.append(s)
            column_sums.append(row_group_sums)

        valid = True
        for j in range(W):
            for sum_val in column_sums[j]:
                if sum_val > K:
