            for row in group:
                for j in range(W):
                    group_sum[j] += S[row][j]
            column_sums.append(group_sum)
        # Now compute vertical cuts
        current_sums = [0] * num_groups
        vertical_cuts = 0
        for j in range(W):
            tentative = [current_sums[i] + column_sums[i][j] for i in range(num_groups)]
            if all(s <= K for s in tentative):
                current_sums = tentative
            else:
                vertical_cuts += 1
                current_sums = [column_sums[i][j] for i in range(num_groups)]
        # total cuts is sum of horizontal cuts (number of 1s in split_points) plus vertical_cuts
        horizontal_cuts = sum(split_points)
        total_cuts = horizontal_cuts + vertical_cuts
        if total_cuts < min_cuts:
            min_cuts = total_cuts
    print(min_cuts)

