def main():
    import sys
    X, Y = map(int, sys.stdin.readline().split())
    memo = {}
    def dfs(a):
        if a > Y:
            return 0
        if a in memo:
            return memo[a]
        next_a = a * 2
        if next_a > Y:
            memo[a] = 1
        else:
            memo[a] = 1 + dfs(next_a)
        return memo[a]
    print(dfs(X))

