    N = int(input[idx])
    idx += 1
    A = []
    for _ in range(N):
        row = list(map(int, input[idx:idx+N]))
        A.append(row)
        idx += N

    # Check validity of the matrix
    for u in range(N):
        for v in range(N):
            for w in range(N):
                if A[u][v] > A[u][w] + A[w][v]:
                    print(-1)
                    return

    # Prim's algorithm to find MST
    INF = float('inf')
    key = [INF] * N
    key[0] = 0
    in_mst = [False] * N
    total = 0

    for _ in range(N):
        # Find the minimum key node not in MST
        u = -1
        min_key = INF
        for i in range(N):
            if not in_mst[i] and key[i] < min_key:
                min_key = key[i]
                u = i
        if u == -1:
            break
        in_mst[u] = True
        total += min_key
        # Update key values for adjacent nodes
        for v in range(N):
            if not in_mst[v] and A[u][v] < key[v]:
                key[v] = A[u][v]

    print(total)

