            groups[0].append(v)
        elif w == w0 + 1:
            groups[1].append(v)
        elif w == w0 + 2:
            groups[2].append(v)
        else:
            groups[3].append(v)

    # Sort each group in descending order and compute prefix sums
    prefix_sums = []
    for g in groups:
        g.sort(reverse=True)
        prefix = [0]
        for v in g:
            prefix.append(prefix[-1] + v)
        prefix_sums.append(prefix)

