                    continue
                for x in range(1, count + 1):
                    new_i = i + x
                    new_s = s + x * o
                    if new_i > N or new_s > max_s:
                        continue
                    if dp[new_i][new_s] < dp[i][s] + prefix[x]:
                        dp[new_i][new_s] = dp[i][s] + prefix[x]

