from collections import defaultdict

def main():
    input = sys.stdin.read().split()
    idx = 0
    N = int(input[idx])
    idx += 1
    W = int(input[idx])
    idx += 1

    groups = defaultdict(list)
    for _ in range(N):
        w = int(input[idx])
        idx += 1
        v = int(input[idx])
        idx += 1
        groups[w].append(v)

    group_list = []
    for w in groups:
        values = groups[w]
        values.sort(reverse=True)
        prefix = [0]
        for v in values:
            prefix.append(prefix[-1] + v)
        group_list.append((w, prefix))

    m = len(group_list) // 2
    part1 = group_list[:m]
    part2 = group_list[m:]

    def generate_combinations(groups):
        combinations = [(0, 0)]
        for (weight, prefix) in groups:
            new_combinations = []
            for (current_weight, current_value) in combinations:
                for count in range(len(prefix)):
                    new_weight = current_weight + count * weight
                    new_value = current_value + prefix[count]
                    new_combinations.append((new_weight, new_value))
            combinations = new_combinations
        return combinations

    part1_combinations = generate_combinations(part1)
    part2_combinations = generate_combinations(part2)

    sorted_combinations = sorted(part2_combinations, key=lambda x: x[0])
    sorted_weights = [c[0] for c in sorted_combinations]
    max_values_so_far = [0] * len(sorted_weights)
    current_max = 0
    for i in range(len(sorted_weights)):
        current_max = max(current_max, sorted_combinations[i][1])
        max_values_so_far[i] = current_max

    max_total = 0
    for (total_weight1, total_value1) in part1_combinations:
        rem = W - total_weight1
        if rem < 0:
            continue
        idx_b = bisect.bisect_right(sorted_weights, rem) - 1
        if idx_b >= 0:
            current_max_val = max_values_so_far[idx_b]
            max_total = max(max_total, total_value1 + current_max_val)

    print(max_total)

