def main():
    import sys
    input = sys.stdin.read().split()
    idx = 0
    H = int(input[idx])
    idx += 1
    W = int(input[idx])
    idx += 1

    cost = []
    for _ in range(10):
        row = list(map(int, input[idx:idx+10]))
        cost.append(row)
        idx += 10

    wall = []
    for _ in range(H):
        row = list(map(int, input[idx:idx+W]))
        wall.append(row)
        idx += W

    # Precompute minimum cost for each digit to reach 1
    min_cost = [0] * 10
    for d in range(10):
        dist = [float('inf')] * 10
        dist[d] = 0
        heap = []
        heapq.heappush(heap, (0, d))
        while heap:
            current_dist, u = heapq.heappop(heap)
            if u == 1:
                break
            if current_dist > dist[u]:
                continue
            for v in range(10):
                new_dist = dist[u] + cost[u][v]
                if new_dist < dist[v]:
                    dist[v] = new_dist
                    heapq.heappush(heap, (new_dist, v))
        min_cost[d] = dist[1]

    total = 0
    for row in wall:
        for cell in row:
            if cell != -1:
                total += min_cost[cell]

    print(total)

