def increment_str(s):
    s_list = list(s)
    i = len(s_list) - 1
    carry = 1
    while i >= 0 and carry:
        digit = int(s_list[i]) + carry
        if digit == 10:
            s_list[i] = '0'
            carry = 1
        else:
            s_list[i] = str(digit)
            carry = 0
        i -= 1
    if carry:
        s_list = ['1'] + s_list
    return ''.join(s_list)

def subtract_strings(a, b):
    len_a = len(a)
    len_b = len(b)
    if len_b < len_a:
        b = '0' * (len_a - len_b) + b
    elif len_b == len_a:
        pass
    else:
        pass  # should not happen
    result = []
    borrow = 0
    for i in range(len_a - 1, -1, -1):
        digit_a = int(a[i])
        digit_b = int(b[i])
        diff = digit_a - digit_b - borrow
        if diff < 0:
            diff += 10
            borrow = 1
        else:
            borrow = 0
        result.append(str(diff))
    result = ''.join(result[::-1])
    result = result.lstrip('0')
    if not result:
        return '0'
    return result

