def generate_candidate(n_str, i):
    digits = list(n_str)
    carry = 1
    for j in range(i, -1, -1):
        new_digit = int(digits[j]) + carry
        if new_digit == 10:
            digits[j] = '0'
            carry = 1
        else:
            digits[j] = str(new_digit)
            carry = 0
            break
    if carry == 1:
        digits = ['1'] + digits
    for j in range(i+1, len(digits)):
        digits[j] = '0'
    return ''.join(digits)

def subtract(x_str, n_str):
    max_len = max(len(x_str), len(n_str))
    x_str = x_str.zfill(max_len)
    n_str = n_str.zfill(max_len)
    result = []
    borrow = 0
    for i in range(max_len - 1, -1, -1):
        x_digit = int(x_str[i])
        n_digit = int(n_str[i])
        diff = x_digit - n_digit - borrow
        if diff < 0:
            diff += 10
            borrow = 1
        else:
            borrow = 0
        result.append(str(diff))
    result = ''.join(result[::-1]).lstrip('0')
    if result == '':
        return '0'
    return result

