import sys
import math
from math import gcd
from collections import defaultdict

def main():
    input = sys.stdin.read().split()
    N = int(input[0])
    A = list(map(int, input[1:N+1]))
    max_A = 10**6
    # Precompute sieve of smallest prime factors
    spf = list(range(max_A + 1))
    for i in range(2, int(math.isqrt(max_A)) + 1):
        if spf[i] == i:  # i is prime
            for j in range(i*i, max_A + 1, i):
                if spf[j] == j:
                    spf[j] = i
    # Function to get unique primes of x
    def get_primes(x):
        primes = set()
        if x == 1:
            return primes
        while x != 1:
            p = spf[x]
            primes.add(p)
            while x % p == 0:
                x //= p
        return primes
    # Count frequency of primes
    freq = defaultdict(int)
    for num in A:
        primes = get_primes(num)
        for p in primes:
            freq[p] += 1
    # Check pairwise
    pairwise = True
    for count in freq.values():
        if count >= 2:
            pairwise = False
            break
    if pairwise:
        print("pairwise coprime")
        return
    # Compute overall GCD
    current_gcd = A[0]
    for num in A[1:]:
        current_gcd = math.gcd(current_gcd, num)
        if current_gcd == 1:
            break
    if current_gcd == 1:
        print("setwise coprime")
    else:
        print("not coprime")

