        if spf[i] == i:  # i is a prime
            for j in range(i * i, max_spf + 1, i):
                if spf[j] == j:
                    spf[j] = i

    # Function to get unique prime factors of a number
    def get_primes(x):
        primes = set()
        if x == 1:
            return primes
        while x != 1:
            p = spf[x]
            primes.add(p)
            while x % p == 0:
                x //= p
        return primes

    primes_seen = set()
    for num in A:
        primes = get_primes(num)
        for p in primes:
            if p in primes_seen:
                print("setwise coprime")
                return
            primes_seen.add(p)
    print("pairwise coprime")

