    min_RL = float('inf')
    has_RL = False

    for _ in range(N):
        x = int(input[idx])
        y = int(input[idx+1])
        d = input[idx+2]
        idx += 3

        # Process x
        if d == 'R':
            has_R = True
            if x > max_R:
                max_R = x
            if x < min_R:
                min_R = x
        elif d == 'L':
            has_L = True
            if x > max_L:
                max_L = x
            if x < min_L:
                min_L = x
        else:
            has_UD = True
            if x > max_UD:
                max_UD = x
            if x < min_UD:
                min_UD = x

        # Process y
        if d == 'U':
            has_U = True
            if y > max_U:
                max_U = y
            if y < min_U:
                min_U = y
        elif d == 'D':
            has_D = True
            if y > max_D:
                max_D = y
            if y < min_D:
                min_D = y
        else:
            has_RL = True
            if y > max_RL:
                max_RL = y
            if y < min_RL:
                min_RL = y

    # Function to compute the product for a given t
    def compute(t):
        # x_max
        x_candidates = []
        if has_R:
            x_candidates.append(max_R + t)
        if has_L:
            x_candidates.append(max_L - t)
        if has_UD:
            x_candidates.append(max_UD)
        x_max = max(x_candidates)

        # x_min
        x_candidates_min = []
        if has_R:
            x_candidates_min.append(min_R + t)
        if has_L:
            x_candidates_min.append(min_L - t)
        if has_UD:
            x_candidates_min.append(min_UD)
        x_min = min(x_candidates_min)

        # y_max
        y_candidates = []
        if has_U:
            y_candidates.append(max_U + t)
        if has_D:
            y_candidates.append(max_D - t)
        if has_RL:
            y_candidates.append(max_RL)
        y_max = max(y_candidates)

