        if has_D:
            y_candidates_min.append(min_D - t)
        if has_RL:
            y_candidates_min.append(min_RL)
        y_min = min(y_candidates_min)

        return (x_max - x_min) * (y_max - y_min)

    # Perform ternary search
    T = 1e14
    left = 0.0
    right = T
    for _ in range(100):
        if right - left < 1e-10:
            break
        m1 = left + (right - left)/3
        m2 = right - (right - left)/3
        f1 = compute(m1)
        f2 = compute(m2)
        if f1 < f2:
            right = m2
        else:
            left = m1

    # Check several points in the final interval
    candidates = [0.0, left, right, (left + right)/2]
    min_val = float('inf')
    for t in candidates:
        current = compute(t)
        if current < min_val:
            min_val = current

    print("{0:.10f}".format(min_val))

