def main():
    H, W, K = map(int, sys.stdin.readline().split())
    x1, y1, x2, y2 = map(int, sys.stdin.readline().split())
    grid = [sys.stdin.readline().strip() for _ in range(H)]

    # Precompute max_north, max_south, max_west, max_east
    max_north = [[0]*(W+1) for _ in range(H+1)]
    max_south = [[0]*(W+1) for _ in range(H+1)]
    max_west = [[0]*(W+1) for _ in range(H+1)]
    max_east = [[0]*(W+1) for _ in range(H+1)]

    # Compute max_north
    for i in range(1, H+1):
        for j in range(1, W+1):
            if grid[i-1][j-1] == '@':
                max_north[i][j] = 0
            else:
                if i == 1:
                    max_north[i][j] = 0
                else:
                    if grid[i-2][j-1] == '@':
                        max_north[i][j] = 0
                    else:
                        max_north[i][j] = 1 + max_north[i-1][j]

    # Compute max_south
    for i in range(H, 0, -1):
        for j in range(1, W+1):
            if grid[i-1][j-1] == '@':
                max_south[i][j] = 0
            else:
                if i == H:
                    max_south[i][j] = 0
                else:
                    if grid[i][j-1] == '@':
                        max_south[i][j] = 0
                    else:
                        max_south[i][j] = 1 + max_south[i+1][j]

    # Compute max_west
    for i in range(1, H+1):
        for j in range(W, 0, -1):
            if grid[i-1][j-1] == '@':
                max_west[i][j] = 0
            else:
                if j == 1:
                    max_west[i][j] = 0
                else:
                    if grid[i-1][j-2] == '@':
                        max_west[i][j] = 0
                    else:
                        max_west[i][j] = 1 + max_west[i][j-1]

    # Compute max_east
    for i in range(1, H+1):
        for j in range(W, 0, -1):
            if grid[i-1][j-1] == '@':
                max_east[i][j] = 0
            else:
                if j == W:
                    max_east[i][j] = 0
                else:
                    if grid[i-1][j] == '@':
                        max_east[i][j] = 0
                    else:
                        max_east[i][j] = 1 + max_east[i][j+1]

    # BFS
    distance = [[-1]*(W+1) for _ in range(H+1)]
    q = deque()
    start_i, start_j = x1, y1
    distance[start_i][start_j] = 0
    q.append((start_i, start_j))

    while q:
        i, j = q.popleft()

        # North
        max_steps = max_north[i][j]
        s = min(K, max_steps)
        if s >= 1:
            new_i = i - s
            new_j = j
            if 1 <= new_i <= H and 1 <= new_j <= W and distance[new_i][new_j] == -1:
                distance[new_i][new_j] = distance[i][j] + 1
                q.append((new_i, new_j))
            new_i1 = i - 1
            new_j1 = j
            if 1 <= new_i1 <= H and 1 <= new_j1 <= W and distance[new_i1][new_j1] == -1:
                distance[new_i1][new_j1] = distance[i][j] + 1
                q.append((new_i1, new_j1))

        # South
        max_steps = max_south[i][j]
        s = min(K, max_steps)
        if s >= 1:
            new_i = i + s
            new_j = j
            if 1 <= new_i <= H and 1 <= new_j <= W and distance[new_i][new_j] == -1:
                distance[new_i][new_j] = distance[i][j] + 1
                q.append((new_i, new_j))
            new_i1 = i + 1
            new_j1 = j
            if 1 <= new_i1 <= H and 1 <= new_j1 <= W and distance[new_i1][new_j1] == -1:
                distance[new_i1][new_j1] = distance[i][j] + 1
                q.append((new_i1, new_j1))

        # East
        max_steps = max_east[i][j]
        s = min(K, max_steps)
        if s >= 1:
            new_i = i
            new_j = j + s
            if 1 <= new_i <= H and 1 <= new_j <= W and distance[new_i][new_j] == -1:
                distance[new_i][new_j] = distance[i][j] + 1
                q.append((new_i, new_j))
            new_i1 = i
            new_j1 = j + 1
            if 1 <= new_i1 <= H and 1 <= new_j1 <= W and distance[new_i1][new_j1] == -1:
                distance[new_i1][new_j1] = distance[i][j] + 1
                q.append((new_i1, new_j1))

        # West
        max_steps = max_west[i][j]
        s = min(K, max_steps)
        if s >= 1:
            new_i = i
            new_j = j - s
            if 1 <= new_i <= H and 1 <= new_j <= W and distance[new_i][new_j] == -1:
                distance[new_i][new_j] = distance[i][j] + 1
                q.append((new_i, new_j))
