        if a == 0 and b == 0:
            Z_count += 1
        else:
            x = a
            y = b
            g = math.gcd(abs(x), abs(y))
            x //= g
            y //= g
            if x == 0:
                if y < 0:
                    y = -y
                dir_key = (0, y)
            else:
                if x < 0:
                    x = -x
                    y = -y
                dir_key = (x, y)
            if dir_key in dir_count:
                dir_count[dir_key] += 1
            else:
                dir_count[dir_key] = 1

    processed = set()
    product = 1

    for dir_key in list(dir_count.keys()):
        if dir_key in processed:
            continue
        x, y = dir_key
        perp_x = y
        perp_y = -x
        perp_dir = normalize(perp_x, perp_y)
        if perp_dir in dir_count:
            if perp_dir in processed:
                continue
            processed.add(dir_key)
            processed.add(perp_dir)
            a = dir_count[dir_key]
            b = dir_count[perp_dir]
            ways = (pow(2, a, MOD) + pow(2, b, MOD) - 1) % MOD
            product = (product * ways) % MOD
        else:
            processed.add(dir_key)
            a = dir_count[dir_key]
            ways = pow(2, a, MOD)
            product = (product * ways) % MOD

    total_NZ = (product - 1) % MOD
    answer = (total_NZ + Z_count) % MOD
    print(answer)

