import sys

def main():
    input = sys.stdin.read().split()
    ptr = 0
    N = int(input[ptr])
    ptr += 1

    S = list(map(int, input[ptr:ptr+N]))
    ptr += N
    T = list(map(int, input[ptr:ptr+N]))
    ptr += N
    U = list(map(int, input[ptr:ptr+N]))
    ptr += N
    V = list(map(int, input[ptr:ptr+N]))
    ptr += N

    matrix = [[0]*N for _ in range(N)]

    for i in range(N):
        for j in range(N):
            row_low = U[i] if S[i] == 0 else 0
            row_high = U[i] if S[i] == 1 else (1 << 64) - 1
            col_low = V[j] if T[j] == 0 else 0
            col_high = V[j] if T[j] == 1 else (1 << 64) - 1
            lower = max(row_low, col_low)
            upper = min(row_high, col_high)
            if lower > upper:
                print(-1)
                return
            matrix[i][j] = lower

    # Process rows with S[i] == 1
    for i in range(N):
        if S[i] == 1:
            current_or = 0
            for j in range(N):
                current_or |= matrix[i][j]
            if current_or != U[i]:
                found = False
                for j in range(N):
                    if matrix[i][j] != U[i]:
                        matrix[i][j] = U[i]
                        found = True
                        break
                if not found:
                    print(-1)
                    return

    # Process columns with T[j] == 0
    for j in range(N):
        if T[j] == 0:
            current_and = (1 << 64) - 1
            for i in range(N):
                current_and &= matrix[i][j]
            if current_and != V[j]:
                found = False
                for i in range(N):
                    if matrix[i][j] != V[j]:
                        matrix[i][j] = V[j]
                        found = True
                        break
                if not found:
                    print(-1)
                    return

    # Check all rows and columns
    for i in range(N):
        if S[i] == 0:
            row_and = matrix[i][0]
            for j in range(1, N):
                row_and &= matrix[i][j]
            if row_and != U[i]:
                print(-1)
                return
        else:
            row_or = matrix[i][0]
            for j in range(1, N):
                row_or |= matrix[i][j]
            if row_or != U[i]:
                print(-1)
                return

    for j in range(N):
        if T[j] == 0:
            col_and = matrix[0][j]
            for i in range(1, N):
                col_and &= matrix[i][j]
            if col_and != V[j]:
                print(-1)
                return
        else:
            col_or = matrix[0][j]
            for i in range(1, N):
                col_or |= matrix[i][j]
            if col_or != V[j]:
                print(-1)
                return

    for row in matrix:
        print(' '.join(map(str, row)))

